package com.sora.splineroads.core;
import com.sora.splineroads.core.RoadGeometry.*;import com.sora.splineroads.core.RoadStructures.*;import java.util.*;
public class Guardrail201Validation{
 static List<V> ends(List<Part> parts,double surface,boolean highway){var counts=new LinkedHashMap<String,Integer>();var positions=new HashMap<String,V>();double width=highway?.3:.12,height=highway?.18:.12,offset=highway?.8:1.05;for(var p:parts)if(p.material()==Material.STEEL&&!p.pier()&&Math.abs(p.width()-width)<1e-8&&Math.abs(p.height()-height)<1e-8&&Math.abs(p.a().y()-surface-offset)<1e-6)for(var v:List.of(p.a(),p.b())){String k=Math.round(v.x()*1e6)+":"+Math.round(v.z()*1e6);positions.put(k,v);counts.merge(k,1,Integer::sum);}return counts.entrySet().stream().filter(e->e.getValue()==1).map(e->positions.get(e.getKey())).toList();}
 public static void main(String[]args)throws Exception{int tips=0,scenarios=0,legacyIntrusions=0;double worst=0;var unsafe=new java.util.TreeSet<String>();boolean dump=Boolean.getBoolean("guardrail.dump");var method=RoadStructures.class.getDeclaredMethod("boundaryRails",List.class,Mesh.class,Ground.class,boolean.class,boolean.class);method.setAccessible(true);if(args.length>0&&args[0].equals("controls")){negativeCases(method);return;}
 for(boolean left:new boolean[]{false,true})for(int count:new int[]{1,2}){var plan=Interchange201Probe.plan(left,count);for(var feed:plan.legs())if(feed.name().startsWith("共用")){var base=plan.legs().get((feed.name().startsWith("共用汇出")?feed.from():feed.to())%2).mesh();var ramp=feed.mesh();if(Math.abs(base.first().center().y()-ramp.first().center().y())>.01)continue;var ms=new ArrayList<Mesh>();for(var m:List.of(base,ramp)){var s=m.settings().structure(m==base?Structure.GROUND:Structure.BRIDGE);ms.add(new Mesh(m.samples(),s,m.min(),m.max(),m.length(),m.closed()));}scenarios++;var partsByRoad=new ArrayList<List<Part>>();
 for(int i=0;i<2;i++){var m=ms.get(i);var other=ms.get(1-i);var join=new RoadRailJoin(m,List.of(new RoadRailJoin.Neighbor(other,i>0)));var ground=new Ground(){public double top(double x,double z,double below){return base.first().center().y();}public boolean joined(V p){return false;}public boolean blocked(Part p){return false;}public boolean railBlocked(Part p,V a,V b){return !RoadRailJoin.sharedRail(other,a,b)&&RoadClearance.structureInvades(p,LaneDeck.motorOnly(other),4.5);}public List<RoadRailJoin.Span> railSpans(V a,V b,V outside,double inset){return join.exposed(a,b,outside,inset);}public V railJoint(V p,V d,boolean h,boolean r){return join.joint(p,d,h,r);}public boolean railPost(V p,boolean h,boolean r){return join.ownsPost(p,h,r);}public boolean unionRails(){return true;}};var parts=new ArrayList<Part>();method.invoke(null,parts,m,ground,true,i==0);RoadStructures.terminalPosts(parts,ground);partsByRoad.add(parts);}
 var hostTips=ends(partsByRoad.get(0),base.first().center().y(),true);var rampTips=ends(partsByRoad.get(1),base.first().center().y(),false);int matched=0;
 for(var a:hostTips){var q=RoadQueries.horizontal(ramp,a);if(q.horizontalDistance()>q.sample().halfWidth()+1)continue;double gap=rampTips.stream().mapToDouble(b->a.sub(b).horizontalLength()).min().orElse(Double.POSITIVE_INFINITY);if(!dump&&gap>.02)throw new AssertionError("disconnected rail nose gap="+gap+" left="+left+" lanes="+count+" feeder="+feed.name()+" host="+a+" rampTips="+rampTips);worst=Math.max(worst,gap);matched++;tips++;}
 if(!dump&&matched!=2)throw new AssertionError("expected taper and nose rail endpoints, got "+matched);
 for(int i=0;i<2;i++)for(var p:partsByRoad.get(i))if((p.material()==Material.STEEL||p.material()==Material.CONCRETE)&&Math.min(p.a().y(),p.b().y())>=base.first().center().y()-.1&&Math.max(p.a().y(),p.b().y())<base.first().center().y()+1.4)if(RoadClearance.structureInvades(p,LaneDeck.motorOnly(ms.get(1-i)),4.5)){
  // The pre-existing taper starts inside the host's outside shoulder. Keep a
  // separate old/new manifest: only newly reconnected nose parts are in scope.
  var q=RoadQueries.horizontal(ramp,p.a().add(p.b()).mul(.5));
  boolean nearNose=q.sample().distance()>ramp.length()*.65;
  if(!feed.name().startsWith("共用汇出"))nearNose=q.sample().distance()<ramp.length()*.35;
  if(!dump&&nearNose)throw new AssertionError("reconnected nose enters motor lane "+p);
  legacyIntrusions++;unsafe.add(left+":"+count+":"+feed.name()+":"+i+":"+p);
 }
 }}if(tips!=64||scenarios!=32)throw new AssertionError("missing expected 32 scenarios / 64 joined tips");negativeCases(method);if(dump)java.nio.file.Files.write(java.nio.file.Path.of(System.getProperty("guardrail.manifest","guardrail-unsafe.txt")),unsafe);System.out.println((dump?"Guardrail201Validation DIAGNOSTIC joinedTips=":"Guardrail201Validation PASS joinedTips=")+tips+" scenarios="+scenarios+" preexistingTaperIntersections="+legacyIntrusions+" maximumXZGap="+worst);}
 static void negativeCases(java.lang.reflect.Method method)throws Exception{
  int off=0,open=0;
  var ground=new Ground(){public double top(double x,double z,double below){return 0;}public boolean joined(V p){return false;}public boolean blocked(Part p){return false;}};
  for(boolean left:new boolean[]{false,true})for(var structure:new Structure[]{Structure.GROUND,Structure.BRIDGE}){
   var s=new Settings(Mode.STRAIGHT,Style.H4_RAIL,28,1,.4,90).structure(structure);s=s.options(s.options().traffic(left).outerRail(RoadProfile.OuterRail.OFF));
   var m=RoadGeometry.build(new Node(new V(0,4,0),0,0),new Node(new V(0,4,80),0,0),s);var parts=new ArrayList<Part>();method.invoke(null,parts,m,ground,true,true);if(!parts.isEmpty())throw new AssertionError("OFF emitted boundary railing");off++;
   final var uncut=m;int outer=LaneAdditions.slots(m,35).stream().max(java.util.Comparator.comparingDouble(slot->LanePoints.lane(uncut,35,slot).position().sub(RoadStructures.sample(uncut,35).center()).dot(RoadStructures.sample(uncut,35).left()))).orElseThrow();var cut=new LaneSections.Cut(UUID.randomUUID(),outer,1,20,55,2,null,true,false,true);s=s.options(s.options().outerRail(RoadProfile.OuterRail.AUTO).lanePoints(s.options().lanePoints().cuts(List.of(cut))));m=RoadGeometry.build(new Node(new V(0,4,0),0,0),new Node(new V(0,4,80),0,0),s);parts.clear();method.invoke(null,parts,m,ground,true,true);
   var at=RoadStructures.sample(m,35);int openings=0;for(int side:new int[]{-1,1})if(LaneDeck.outerOpening(m,35,side)){openings++;var point=at.at(side*(at.halfWidth()-RoadRailJoin.INSET),-.8);for(var p:parts)if(p.material()==Material.STEEL&&p.width()==.3){var v=p.b().sub(p.a());double f=Math.max(0,Math.min(1,point.sub(p.a()).dot(v)/v.dot(v)));if(point.distance(p.a().add(v.mul(f)))<.1)throw new AssertionError("closed outer lane regained rail across opening");}}if(openings==0)throw new AssertionError("fixture has no outer opening");open++;
  }System.out.println("Guardrail201 OFF/opening controls="+off+"/"+open);
 }

}
